const items = $input.all();
const pages = [];
for (const item of items) {
  const results = item.json.results || [];
  for (const page of results) {
    const props = page.properties || {};
    const titleArr = props['Title'] && props['Title'].title ? props['Title'].title : [];
    const toolArr = props['Tool Mentioned'] && props['Tool Mentioned'].rich_text ? props['Tool Mentioned'].rich_text : [];
    const subArr = props['Subreddit'] && props['Subreddit'].rich_text ? props['Subreddit'].rich_text : [];
    pages.push({
      source: props['Source'] && props['Source'].select ? props['Source'].select.name : 'Unknown',
      intent: props['Intent'] && props['Intent'].select ? props['Intent'].select.name : 'unknown',
      boosted_score: props['Boosted Score'] && props['Boosted Score'].number !== null ? props['Boosted Score'].number : 0,
      tool_mentioned: toolArr[0] ? toolArr[0].plain_text.toLowerCase().trim() : '',
      subreddit: subArr[0] ? subArr[0].plain_text : '',
      title: titleArr[0] ? titleArr[0].plain_text : '',
      url: props['URL'] && props['URL'].url ? props['URL'].url : '',
    });
  }
}
const bySource = {};
pages.forEach(p => { bySource[p.source] = (bySource[p.source] || 0) + 1; });
const byIntent = {};
pages.forEach(p => { byIntent[p.intent] = (byIntent[p.intent] || 0) + 1; });
const topIntent = Object.entries(byIntent).sort((a, b) => b[1] - a[1])[0]?.[0] || 'N/A';
const hotCount = pages.filter(p => p.boosted_score >= 8).length;
const top5Leads = [...pages].sort((a, b) => b.boosted_score - a.boosted_score).slice(0, 5);
const competitors = {};
pages.forEach(p => { if (p.tool_mentioned) competitors[p.tool_mentioned] = (competitors[p.tool_mentioned] || 0) + 1; });
const top3Competitors = Object.entries(competitors).sort((a, b) => b[1] - a[1]).slice(0, 3);
const subreddits = {};
pages.forEach(p => { if (p.subreddit) subreddits[p.subreddit] = (subreddits[p.subreddit] || 0) + 1; });
const topSubreddit = Object.entries(subreddits).sort((a, b) => b[1] - a[1])[0]?.[0] || 'N/A';
const now = new Date();
const weekAgo = new Date(now - 7*24*60*60*1000);
const fmt = d => d.toLocaleDateString('en-IN', {timeZone:'Asia/Kolkata', day:'numeric', month:'short', year:'numeric'});
const dateRange = `${fmt(weekAgo)} – ${fmt(now)}`;
const sourceStr = Object.entries(bySource).map(([k,v]) => `${k}: ${v}`).join(', ') || 'none';
const competitorStr = top3Competitors.map(([name,count],i) => `${i+1}. ${name} (${count})`).join(', ') || 'none';
const topLeadStr = top5Leads.length > 0 ? `"${top5Leads[0].title}" — Score: ${top5Leads[0].boosted_score}` : 'N/A';
const geminiPrompt = `You are a business analyst for Elvan.ai, a B2B SaaS NPS/CSAT/CES survey platform.\n\nWrite a 3-4 sentence narrative summary of this week's signal intelligence. Focus on key patterns, buying intent, and what the team should prioritize. No bullet points. Plain text only.\n\nWeekly data (${dateRange}):\n- Total signals: ${pages.length}\n- Hot leads (score ≥ 8): ${hotCount}\n- By source: ${sourceStr}\n- Dominant intent: ${topIntent}\n- Top competitors: ${competitorStr}\n- Hottest lead: ${topLeadStr}`;
return [{json:{total:pages.length,hot_count:hotCount,by_source:bySource,top_intent:topIntent,top5_leads:top5Leads,top3_competitors:top3Competitors,top_subreddit:topSubreddit,date_range:dateRange,gemini_prompt:geminiPrompt}}];

const items = $input.all();
return items.map(item => {
  const narrative = (item.json.text || item.json.output || item.json.response || '').trim();
  return { json: { ...item.json, narrative } };
});

const notionId = $json.id ? $json.id.replace(/-/g,'') : '';
const notionUrl = notionId ? `https://www.notion.so/${notionId}` : 'N/A';
const stats = $('Parse Narrative').item.json;
const sourceStr = Object.entries(stats.by_source||{}).map(([k,v])=>`${k} (${v})`).join(' | ') || 'N/A';
const competitorLines = (stats.top3_competitors||[]).map(([name,count],i)=>`${i+1}. ${name} — ${count} mentions`).join('
') || 'None this week';
const hotLead = stats.top5_leads && stats.top5_leads.length > 0 ? stats.top5_leads[0] : null;
const hotLeadStr = hotLead ? `${hotLead.title} — Score: ${hotLead.boosted_score}
${hotLead.url}` : 'N/A';
const message = `📈 Weekly Signal Report — ${stats.date_range}

📊 Total Signals: ${stats.total}
🔥 Hot Leads: ${stats.hot_count}
📡 Sources: ${sourceStr}

🏆 Top Competitors Mentioned:
${competitorLines}

💡 Top Intent: ${stats.top_intent}

🎯 Hottest Lead This Week:
${hotLeadStr}

📝 Summary:
${stats.narrative}

Full report → ${notionUrl}`;
return {json:{message}};
